'use strict';

/**
 * Least-recently-used cache.
 *
 * Backed by a single Map, whose iteration order is insertion order: the first
 * key is the least recently used and the last key is the most recently used.
 * Refreshing an entry is done by deleting and re-inserting it, so every
 * operation is O(1) and keys follow Map (SameValueZero) semantics.
 */
class LRUCache {
  #capacity;
  #map = new Map();

  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError(`LRUCache capacity must be a positive integer, got ${String(capacity)}`);
    }
    this.#capacity = capacity;
  }

  get capacity() {
    return this.#capacity;
  }

  get(key) {
    const map = this.#map;
    // Check with has() so entries whose value is undefined still get refreshed.
    if (!map.has(key)) return undefined;
    const value = map.get(key);
    map.delete(key);
    map.set(key, value);
    return value;
  }

  set(key, value) {
    const map = this.#map;
    if (map.has(key)) {
      // Update in place: re-insert to mark most recently used; size unchanged.
      map.delete(key);
    } else if (map.size >= this.#capacity) {
      map.delete(map.keys().next().value);
    }
    map.set(key, value);
    return this;
  }

  has(key) {
    return this.#map.has(key);
  }

  delete(key) {
    return this.#map.delete(key);
  }

  get size() {
    return this.#map.size;
  }
}

module.exports = { LRUCache };

'use strict';
const assert = require('node:assert/strict');
const { LRUCache } = require('{temp}/hb-d0b9d510-p8pjn6j6/src/lru');

for (const bad of [0, -1, 1.5, Infinity, -Infinity, NaN, '2', undefined, null, 2n, new Number(2), true, []]) {
  assert.throws(() => new LRUCache(bad), RangeError, String(bad));
}
assert.throws(() => new LRUCache(), RangeError);
new LRUCache(1); new LRUCache(Number.MAX_SAFE_INTEGER);

// undefined value refreshed by get
let c = new LRUCache(2);
c.set('a', undefined).set('b', 1);
assert.equal(c.get('a'), undefined);
c.set('c', 2);
assert.equal(c.has('a'), true); assert.equal(c.has('b'), false);

// update doesn't evict / grow, and refreshes
c = new LRUCache(2);
c.set('a', 1).set('b', 2).set('a', 3);
assert.equal(c.size, 2); assert.equal(c.get('a'), 3); assert.equal(c.has('b'), true);
c.set('c', 4);
assert.equal(c.has('b'), false); assert.equal(c.has('a'), true);

// has doesn't refresh
c = new LRUCache(2);
c.set('a', 1).set('b', 2); c.has('a'); c.set('c', 3);
assert.equal(c.has('a'), false);

// delete preserves relative order
c = new LRUCache(3);
c.set('a', 1).set('b', 2).set('c', 3); c.delete('b'); c.set('d', 4); c.set('e', 5);
assert.deepEqual(['a', 'c', 'd', 'e'].map(k => c.has(k)), [false, true, true, true]);

// Map key semantics
c = new LRUCache(5);
const o = {};
c.set(NaN, 'n').set(-0, 'z').set(o, 'o');
assert.equal(c.get(NaN), 'n'); assert.equal(c.get(0), 'z'); assert.equal(c.get(o), 'o'); assert.equal(c.get({}), undefined);

// independence
const x = new LRUCache(1), y = new LRUCache(1);
x.set('k', 1); assert.equal(y.has('k'), false); assert.equal(y.size, 0);
console.log('extra checks ok');
